<?php require __DIR__.'/bootstrap.php';$u=require_admin();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$type=$_POST['source_type']??'upload';$url='';if(!$title)$err='Informe o título do vídeo.';elseif($type==='youtube'){$url=trim($_POST['youtube_url']??'');if(!filter_var($url,FILTER_VALIDATE_URL)||!preg_match('~(youtube\.com|youtu\.be)~i',$url))$err='Informe um link válido do YouTube.';}else{if(empty($_FILES['video']['tmp_name']))$err='Selecione um vídeo MP4 ou WebM.';else{$f=$_FILES['video'];$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['mp4','webm'],true)||$f['size']>500*1024*1024)$err='Use MP4/WebM de até 500 MB.';else{$dir=__DIR__.'/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$file=bin2hex(random_bytes(12)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$file))$err='Não foi possível salvar o arquivo.';else $url='uploads/'.$file;}}}if(!$err){$pub=$u['publisher_id']?:default_publisher();$pdo->prepare("INSERT INTO exclusive_videos(publisher_id,uploaded_by,title,description,video_url,status,published_at) VALUES(?,?,?,?,?,'published',NOW())")->execute([$pub,$u['id'],$title,$desc,$url]);flash('ok','Vídeo publicado para os assinantes Ultimate.');header('Location: admin.php');exit;}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Publicar vídeo — Administração</title><link rel="stylesheet" href="assets/app.css"></head><body class="adminskin"><aside class="side"><a class="side-logo">ARENA DE <b>AÇO</b><small>ADMINISTRAÇÃO</small></a><a href="admin.php">⌂ Dashboard</a><a class="active" href="video_novo.php">▻ Vídeos Ultimate</a><a href="admin_tickets.php">♧ Suporte</a></aside><main class="adminmain"><header class="adminhead"><div><h1>Publicar vídeo Ultimate</h1><span>Somente assinantes Ultimate conseguem assistir.</span></div></header><section class="panel publish"><p class="muted">Você pode enviar o arquivo para a hospedagem ou informar um vídeo do YouTube. Para conteúdo realmente exclusivo, prefira o upload direto ou YouTube não listado.</p><?php if($err):?><p class="alert err"><?=e($err)?></p><?php endif?><form method="post" enctype="multipart/form-data"><label>Título do vídeo<input required name="title" maxlength="180" placeholder="Ex.: Bastidores do capítulo 04"></label><label>Descrição<textarea name="description" placeholder="Conte aos assinantes o que há neste vídeo"></textarea></label><label>Origem do vídeo<select name="source_type" id="source-type"><option value="upload">Enviar arquivo para a Arena</option><option value="youtube">Usar link do YouTube</option></select></label><div id="upload-field"><label>Arquivo (MP4 ou WebM, máximo 500 MB)<input name="video" type="file" accept="video/mp4,video/webm"></label></div><div id="youtube-field" hidden><label>Link YouTube<input name="youtube_url" placeholder="https://youtube.com/watch?v=..."></label></div><button class="redbtn">Publicar para Ultimate →</button></form></section></main><script>const s=document.querySelector('#source-type'),a=document.querySelector('#upload-field'),b=document.querySelector('#youtube-field');s.onchange=()=>{a.hidden=s.value==='youtube';b.hidden=s.value!=='youtube'};</script></body></html>
